// 5. NODO DECISOR INTELIGENTE CON CONTROL DE CAPACIDAD MADE-TO-ORDER
// Filtra y prioriza productos evaluando capacidad disponible en cocina
const hoy = new Date().toISOString().split('T')[0];

// Extraer datos de nodos previos
const productosRaw = $('2. Supabase: Productos Disponibles con Capacidad').all().map(i => i.json);
const eventos = $('3. Supabase: Eventos Calendario').all().map(i => i.json);
const reglas = $('4. Supabase: Reglas Activas').all().map(i => i.json).sort((a,b) => (b.prioridad || 0) - (a.prioridad || 0));

// Filtrar estrictamente productos DISPONIBLES con cupos libres
const productos = productosRaw
  .map(p => {
    const cap = Math.max(1, Number(p.production_capacity) || 10);
    const ord = Math.max(0, Number(p.current_orders) || 0);
    return {
      ...p,
      production_capacity: cap,
      current_orders: ord,
      remaining_capacity: Math.max(0, cap - ord),
      availability_status: p.availability_status || (ord >= cap ? 'CERRADO' : ord >= cap * 0.8 ? 'CAPACIDAD LIMITADA' : 'DISPONIBLE')
    };
  })
  .filter(p => p.availability_status === 'DISPONIBLE' && p.remaining_capacity > 0)
  .sort((a, b) => b.remaining_capacity - a.remaining_capacity);

if (!productos.length) {
  return [{
    json: {
      skip_execution: true,
      motivo: 'Capacidad agotada en cocina. No hay productos en estado DISPONIBLE para promocionar hoy.'
    }
  }];
}

// 1. Buscar evento activo en calendario
const eventoActual = eventos.find(e => {
  const ini = e.fecha_inicio;
  const fin = e.fecha_fin;
  return hoy >= ini && hoy <= fin;
}) || null;

let productoElegido = null;
let reglaElegida = null;
let descuento = 10;
let motivo = 'Promoción optimizada por alta capacidad disponible';

// Coincidencia con evento activo si el producto tiene cupos disponibles
if (eventoActual && eventoActual.productos_relacionados && eventoActual.productos_relacionados.length > 0) {
  productoElegido = productos.find(p => 
    eventoActual.productos_relacionados.some(rel => p.nombre.toLowerCase().includes(rel.toLowerCase()))
  );
  if (productoElegido) {
    reglaElegida = reglas.find(r => r.condicion?.tipo === 'evento_calendario') || reglas[0];
    descuento = reglaElegida ? reglaElegida.descuento_min || 15 : 15;
    motivo = `Asociado al evento: ${eventoActual.nombre} (${productoElegido.remaining_capacity} cupos libres)`;
  }
}

// Si no coincide con evento, tomar producto disponible con mayor capacidad remanente
if (!productoElegido) {
  productoElegido = productos[0];
  reglaElegida = reglas[0] || { id: null, nombre: 'Regla Capacidad', descuento_min: 10, descuento_max: 15 };
  descuento = reglaElegida.descuento_min || 10;
  motivo = `Mayor disponibilidad en cocina: ${productoElegido.remaining_capacity} cupos (${productoElegido.current_orders}/${productoElegido.production_capacity} pedidos)`;
}

const precioOriginal = Number(productoElegido.precio_venta) || 25000;
const precioFinal = Math.round(precioOriginal * (1 - descuento / 100));

return [{
  json: {
    decision_timestamp: new Date().toISOString(),
    producto: productoElegido,
    regla: reglaElegida,
    evento: eventoActual,
    descuento_aplicado: descuento,
    precio_original: precioOriginal,
    precio_final: precioFinal,
    capacidad: {
      production_capacity: productoElegido.production_capacity,
      current_orders: productoElegido.current_orders,
      remaining_capacity: productoElegido.remaining_capacity,
      availability_status: productoElegido.availability_status
    },
    motivo: motivo
  }
}];

// 6. GENERADOR DE PROMPTS Y BRIEFS CREATIVOS PARA CLOUDINARY Y GEMINI
const decision = $input.first().json;
if (decision.skip_execution) {
  return [{ json: decision }];
}

const p = decision.producto;
const d = decision.descuento_aplicado;
const ev = decision.evento;

// Brief creativo para fondo generativo de Cloudinary (IA solo diseña el entorno, NO los precios)
const briefCreativo = `Rustic gourmet artisanal bakery studio setting with warm natural morning lighting, wooden table with soft rice flour dust, aesthetic background for ${p.nombre}, theme: ${ev ? ev.nombre : 'artisan bakery promo'}, 8k resolution advertising shot`;

return [{
  json: {
    ...decision,
    brief_creativo: briefCreativo
  }
}];

